#!/bin/bash
# shellcheck disable=SC1091,SC2034,SC2317,SC2329

# WARNING: Please DO NOT edit this file! It is maintained in the Repository Template (https://github.com/nhs-england-tools/repository-template). Raise a PR instead.

set -euo pipefail

# Test suite for Docker functions.
#
# Usage:
#   $ ./docker.test.sh
#
# Arguments (provided as environment variables):
#   VERBOSE=true  # Show all the executed commands, default is 'false'

# ==============================================================================

function main() {

  cd "$(git rev-parse --show-toplevel)"
  source ./scripts/docker/docker.lib.sh
  cd ./scripts/docker/tests

  DOCKER_IMAGE=repository-template/docker-test
  DOCKER_TITLE="Repository Template Docker Test"

  test-docker-suite-setup
  tests=( \
    test-docker-build \
    test-docker-image-from-signature \
    test-docker-legacy-tool-versions \
    test-docker-no-matching-docker-version \
    test-docker-version-file \
    test-docker-test \
    test-docker-run \
    test-docker-clean \
    test-docker-get-image-version-and-pull \
  )
  local status=0
  for test in "${tests[@]}"; do
    {
      echo -n "$test"
      # shellcheck disable=SC2015
      $test && echo " PASS" || { echo " FAIL"; ((status++)); }
    }
  done
  echo "Total: ${#tests[@]}, Passed: $(( ${#tests[@]} - status )), Failed: $status"
  test-docker-suite-teardown
  [ $status -gt 0 ] && return 1 || return 0
}

# ==============================================================================

function test-docker-suite-setup() {

  :
}

function test-docker-suite-teardown() {

  :
}

# ==============================================================================

function test-docker-build() {

  # Arrange
  export BUILD_DATETIME="2023-09-04T15:46:34+0000"
  # Act
  docker-build > /dev/null 2>&1
  # Assert
  docker image inspect "${DOCKER_IMAGE}:$(_get-effective-version)" > /dev/null 2>&1 && return 0 || return 1
}

function test-docker-image-from-signature() {

  # Arrange
  local DOCKER_VERSIONS
  DOCKER_VERSIONS="$(git rev-parse --show-toplevel)/scripts/docker/tests/.docker-versions.test"
  cp Dockerfile Dockerfile.effective
  # Act
  DOCKER_VERSIONS="$DOCKER_VERSIONS" _replace-image-latest-by-specific-version
  # Assert
  grep -q "FROM python:.*-alpine.*@sha256:.*" Dockerfile.effective && return 0 || return 1
}

function test-docker-legacy-tool-versions() {

  local DOCKER_VERSIONS=""
  local test_dir
  test_dir=$(mktemp -d)
  cp Dockerfile "$test_dir/Dockerfile.effective"
  cp .tool-versions.test "$test_dir/.tool-versions"

  TOOL_VERSIONS="$test_dir/.tool-versions" dir="$test_dir" _replace-image-latest-by-specific-version
  grep -q "FROM python:3.11.4-alpine3.18@sha256:" "$test_dir/Dockerfile.effective" || {
    rm -rf "$test_dir"
    return 1
  }

  printf '%s\n' '# docker/python 3.12.0-alpine@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' > "$test_dir/.docker-versions"
  cp Dockerfile "$test_dir/Dockerfile.effective"
  TOOL_VERSIONS="$test_dir/.tool-versions" dir="$test_dir" _replace-image-latest-by-specific-version
  grep -q "FROM python:3.12.0-alpine@sha256:aaaaaaaa" "$test_dir/Dockerfile.effective"
  local result=$?
  rm -rf "$test_dir"
  return "$result"
}

function test-docker-no-matching-docker-version() {

  local DOCKER_VERSIONS
  local test_dir
  test_dir=$(mktemp -d)
  cp Dockerfile "$test_dir/Dockerfile.effective"
  printf '%s\n' '# docker/example/other-image 1.0.0@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' > "$test_dir/.docker-versions"

  DOCKER_VERSIONS="$test_dir/.docker-versions" dir="$test_dir" _replace-image-latest-by-specific-version
  grep -q '^FROM python:latest$' "$test_dir/Dockerfile.effective" || {
    rm -rf "$test_dir"
    return 1
  }

  docker() {
    case "$1" in
      images) printf 'REPOSITORY TAG\n' ;;
      pull) return 0 ;;
    esac
  }
  local image_version
  image_version=$(DOCKER_VERSIONS="$test_dir/.docker-versions" name=python docker-get-image-version-and-pull)
  local result=$?
  unset -f docker
  rm -rf "$test_dir"
  [ "$result" -eq 0 ] && [ "$image_version" = "python:latest" ]
}

function test-docker-version-file() {

  # Arrange
  export BUILD_DATETIME="2023-09-04T15:46:34+0000"
  # Act
  version-create-effective-file
  # Assert
  # shellcheck disable=SC2002
  (
      cat .version | grep -q "20230904-" &&
      cat .version | grep -q "2023.09.04-" &&
      cat .version | grep -q "somme-name-yyyyeah"
  ) && return 0 || return 1
}

function test-docker-test() {

  # Arrange
  cmd="python --version"
  check="Python"
  # Act
  output=$(docker-check-test)
  # Assert
  echo "$output" | grep -q "PASS"
}

function test-docker-run() {

  # Arrange
  cmd="python --version"
  # Act
  output=$(docker-run)
  # Assert
  echo "$output" | grep -Eq "Python [0-9]+\.[0-9]+\.[0-9]+"
}

function test-docker-clean() {

  # Arrange
  version="$(_get-effective-version)"
  # Act
  docker-clean
  # Assert
  docker image inspect "${DOCKER_IMAGE}:${version}" > /dev/null 2>&1 && return 1 || return 0
}

function test-docker-get-image-version-and-pull() {

  # Arrange
  name="ghcr.io/nhs-england-tools/github-runner-image"
  match_version=".*-rt.*"
  # Act
  docker-get-image-version-and-pull > /dev/null 2>&1
  # Assert
  docker images \
    --filter=reference="$name" \
    --format "{{.Tag}}" \
  | grep -vq "<none>"
}

# ==============================================================================

function is-arg-true() {

  if [[ "$1" =~ ^(true|yes|y|on|1|TRUE|YES|Y|ON)$ ]]; then
    return 0
  else
    return 1
  fi
}

# ==============================================================================

is-arg-true "${VERBOSE:-false}" && set -x

main "$@"

exit 0
